      "keystrokes": "cat > /app/encode.py << 'PYEOF'
#!/usr/bin/env python3
RADIX = 255
OFF1 = 5
OFF2 = 2
LITSIZE = 4

class ArithEnc:
    def __init__(self):
        self.low = 0
        self.rng = 1
        self.counts = {}
        self.ndig = 0

    def _c(self, ctx):
        if ctx not in self.counts:
            self.counts[ctx] = [0, 0]
        return self.counts[ctx]

    def bit(self, b, ctx):
        while self.rng < RADIX:
            self.ndig += 1
            self.low *= RADIX
            self.rng *= RADIX
        c = self._c(ctx)
        split = self.rng * (c[0] + 1) // (c[0] + c[1] + 2)
        if b:
            self.low += split
            self.rng -= split
        else:
            self.rng = split
        c[b] += 1

    def integer(self, val, tmp, ctx):
        sub = 1 << tmp
        k = 0
        while val >= ((1 << (k + 1)) - 1) * sub:
            k += 1
        c99 = ctx * 99
        for j in range(k):
            self.bit(0, tmp + 1 + j + c99)
        self.bit(1, tmp + 1 + k + c99)
        nb = tmp + k
        bp = val + sub - (1 << nb)
        for j in range(nb - 1, -1, -1):
            self.bit((bp >> j) & 1, c99)

def est_bits(val, tmp):
    sub = 1 << tmp
    k = 0
    while val >= ((1 << (k + 1)) - 1) * sub:
        k += 1
    return (k + 1) + (tmp + k)

with open('/app/data.txt', 'rb') as f:
    data = f.read()

data_ext = data + b'\x00'
n = len(data_ext)

ht = {}
for i in range(n - 1):
    key = data_ext[i:i+2]
    if key not in ht:
        ht[key] = []
    ht[key].append(i)

tokens = []
pos = 0
while pos < n:
    best_len = 0
    best_off = 0
    if pos + 1 < n:
        key = data_ext[pos:pos+2]
        if key in ht:
            cnt = 0
            for cp in reversed(ht[key]):
                if cp >= pos:
                    continue
                cnt += 1
                if cnt > 300:
                    break
                off = pos - cp
                ln = 0
                while pos + ln < n and data_ext[cp + ln] == data_ext[pos + ln]:
                    ln += 1
                if ln > best_len:
                    best_len = ln
                    best_off = off

    use_match = False
    if best_len >= 2:
        mc = 1 + est_bits(best_off - 1, OFF1) + est_bits(best_len - 1, OFF2)
        lc = best_len * 7
        if mc < lc:
            use_match = True

    if use_match:
        tokens.append(('m', best_off - 1, best_len - 1))
        pos += best_len
    else:
        tokens.append(('l', data_ext[pos]))
        pos += 1

enc = ArithEnc()
enc.integer(len(tokens), 9, 0)
for t in tokens:
    if t[0] == 'm':
        enc.bit(1, 1)
        enc.integer(t[1], OFF1, 2)
        enc.integer(t[2], OFF2, 3)
    else:
        v = t[1]
        enc.bit(0, 1)
        if v < 128:
            enc.bit(0, 8)
            enc.integer(v, LITSIZE, 9)
        else:
            enc.bit(1, 8)
            enc.integer(256 - v, LITSIZE, 9)

V = enc.low
digits = []
for _ in range(enc.ndig):
    digits.append(V % RADIX)
    V //= RADIX
digits.reverse()
assert V == 0, f"V not zero: {V}"
output = bytes(d + 1 for d in digits)
assert 0 not in output, "output has null byte"

with open('/app/data.comp', 'wb') as f:
    f.write(output)

print(f"Data: {len(data)}, Tokens: {len(tokens)}, Digits: {enc.ndig}, Output: {len(output)}")
PYEOF
